query:
// GraphRAG-Demo-Labels: T3Doc / T3Chunk / T3Entity ; Rels: PART_OF, MENTIONS.
// Loesung nutzt T3UDoc/T3UChunk/T3UEntity, T2/04 nutzt T4Chunk. Fuer eigene Daten Labels anpassen.
// Parametrisierte Queries brauchen vorher gesetzte Parameter, z.B.:  :param doc_id => 'madeira'
RETURN 'Hinweise zur Nutzung stehen als Kommentar im jeweiligen Query-Text' AS info

// :param doc_a => 'madeira'    :param doc_b => 'gardasee'
MATCH (a:T3Doc {doc_id: $doc_a})-[:MENTIONS]->(e:T3Entity)<-[:MENTIONS]-(b:T3Doc {doc_id: $doc_b})
RETURN e.name AS gemeinsame_entity, e.type AS typ

CALL apoc.periodic.iterate(
  'MATCH (n) RETURN n',
  'DETACH DELETE n',
  {batchSize: 10000}
)

// In Neo4j 5 laesst sich 'alle Indizes droppen' nicht in einem Statement machen.
// Schritt 1: diese Query ausfuehren -> Spalte drop_statement liefert fertige DROP-Zeilen.
// Schritt 2: die ausgegebenen Zeilen ausfuehren (droppt auch Vector-Indizes).
SHOW INDEXES YIELD name, type
WHERE type <> 'LOOKUP'
RETURN 'DROP INDEX `' + name + '` IF EXISTS;' AS drop_statement

// Wie [3]: erst ausfuehren, dann die ausgegebenen Zeilen laufen lassen.
SHOW CONSTRAINTS YIELD name
RETURN 'DROP CONSTRAINT `' + name + '` IF EXISTS;' AS drop_statement
